import test from 'node:test';import assert from 'node:assert/strict';import {bindBonusEvidenceProtocol} from './operator-bonus-repair.mjs';import {assertSnapshotSetsUnchanged} from './verify-bonus-repair.mjs';
test('operator protocol binds the actual verified object, snapshot and acceptance without allowing caller overrides',async()=>{const evidence={acceptance:{actual:true}},snapshot={run:{id:1}},context={evidence,snapshot,revalidate:async()=>true};let received;const protocol=bindBonusEvidenceProtocol(async()=>context,args=>{received=args;return {target:'alpha-staging'};});assert.equal(await protocol.verify({}),evidence);assert.equal(await protocol.revalidate(evidence),true);assert.deepEqual(protocol.createGrant({evidence,baselineBuildId:'actual',environmentSha256:'x',snapshot:{forged:true},acceptance:{forged:true}}),{target:'alpha-staging'});assert.equal(received.snapshot,snapshot);assert.equal(received.acceptance,evidence.acceptance);assert.equal(protocol.kind,'runtime-owner-exception/v1');await assert.rejects(protocol.verify({}));await assert.rejects(protocol.revalidate({...evidence}));assert.throws(()=>protocol.createGrant({evidence:{...evidence}}));});
test('no grant or revalidation exists before successful verification',async()=>{const protocol=bindBonusEvidenceProtocol(async()=>{throw Error('actual failure');},()=>{throw Error('never');});assert.throws(()=>protocol.createGrant({evidence:{}}));await assert.rejects(protocol.revalidate({}));await assert.rejects(protocol.verify({}),/actual failure/);await assert.rejects(protocol.verify({}),/already bound/);});
test('parallel verification cannot replace an in-flight evidence binding',async()=>{let finish;const promise=new Promise(resolve=>{finish=resolve;}),evidence={};const protocol=bindBonusEvidenceProtocol(async()=>{await promise;return {evidence,snapshot:{},revalidate:async()=>true};},()=>({}));const first=protocol.verify({});await assert.rejects(protocol.verify({}),/already bound/);finish();assert.equal(await first,evidence);});
const fixture=()=>new Map([[1,{run:{id:1,run_attempt:1,status:'completed',conclusion:'success',head_sha:'a',head_branch:'feature'},jobs:[{id:2,name:'selected-tests',status:'completed',conclusion:'success',run_id:1,run_attempt:1,head_sha:'a',started_at:'a',completed_at:'b',steps:[{name:'actual',conclusion:'success'}]}],artifacts:[{id:3,name:'actual',digest:'sha256:aaa',size_in_bytes:1,expired:false}]}]]);
test('fresh metadata must retain the complete actual identity and every executed job step',()=>assert.equal(assertSnapshotSetsUnchanged(fixture(),fixture()),true));
for(const [name,mutate] of [['rerun',s=>s.get(1).run.run_attempt=2],['failed run',s=>s.get(1).run.conclusion='failure'],['other source',s=>s.get(1).run.head_sha='b'],['changed job step',s=>s.get(1).jobs[0].steps[0].conclusion='failure'],['changed bytes',s=>s.get(1).artifacts[0].digest='other'],['expired archive',s=>s.get(1).artifacts[0].expired=true],['omitted run',s=>s.delete(1)],['missing job',s=>s.get(1).jobs=[]]])test('revalidation refuses '+name,()=>{const after=fixture();mutate(after);assert.throws(()=>assertSnapshotSetsUnchanged(fixture(),after));});
